import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.BGlkWkwp.js";const k=JSON.parse('{"title":"Text","description":"","frontmatter":{},"headers":[],"relativePath":"components/text.md","filePath":"components/text.md"}'),i={name:"components/text.md"};function o(n,e,r,h,l,c){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h1><p>Text is text in one of the nine type roles of the <a href="./../tokens">tokens</a>.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for every piece of interface text outside a control: titles, paragraphs, captions, labels, values. The role sets the size, leading, tracking, weight and element: <code>title</code> and <code>h1</code> are an h1, <code>h2</code> an h2, <code>body</code> and <code>prose</code> a p, and the rest a span shown as a block. Long text written as HTML goes in a <a href="./prose">Prose</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>role</code></td><td><code>body</code></td><td>One of the nine type roles</td></tr><tr><td><code>as</code></td><td></td><td>Another element (<code>a</code>, <code>label</code>, <code>dt</code>, <code>dd</code> …)</td></tr><tr><td><code>clamp</code></td><td><code>false</code></td><td>One line and an ellipsis; the full text on hover</td></tr><tr><td><code>lines</code></td><td></td><td><code>2</code>: two lines and an ellipsis</td></tr><tr><td><code>wrap</code></td><td><code>false</code></td><td>Keeps line breaks and wraps long words</td></tr><tr><td><code>muted</code></td><td><code>false</code></td><td>The muted text color</td></tr><tr><td><code>mono</code></td><td><code>false</code></td><td>The monospace font, at the role&#39;s size</td></tr><tr><td><code>tabular</code></td><td><code>false</code></td><td>Figures of equal width</td></tr><tr><td><code>href</code></td><td></td><td>The target, with <code>as=&quot;a&quot;</code></td></tr><tr><td><code>for</code></td><td></td><td>The labelled control, with <code>as=&quot;label&quot;</code></td></tr><tr><td><code>id</code></td><td></td><td>The element&#39;s id</td></tr><tr><td><code>children</code></td><td></td><td>The text</td></tr><tr><td><code>end</code></td><td></td><td>A mark at the end of the first line (a snippet)</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Text has no margin and keeps its full line box, so its distance to its neighbours is the gap of a Stack or Row plus its leading. It is trimmed to its ink in three places only: inside a component that declares its height (and there it stays on one line), at the inner edge of a container, and next to a line. A link made with <code>as=&quot;a&quot;</code> keeps the color of the text around it and is underlined on hover.</p><p><code>end</code> puts a mark at the end of the text&#39;s first line: a <a href="./badge">Badge</a> beside a title, or a borderless icon button. The text and the end sit in one line, aligned by their first baseline, gap-sm apart. The end is a seat of no height, so the mark is centred on the ink of the first line and hangs without making the line taller (<a href="./../measuring#a-mark-beside-text">a mark beside text</a>). At the edge of a container the mark hangs into the padding, and the line keeps the height of its ink. The text wraps its own words; the end does not move to a line of its own.</p><div class="language-svelte vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">svelte</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Text</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> role</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;h2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Team plan{#</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">snippet</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> end</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()}&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Badge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Current&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Badge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">snippet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/text/" title="Text" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/text/" target="_blank" rel="noopener">Text</a></figcaption></figure>',12)])])}const g=t(i,[["render",o]]);export{k as __pageData,g as default};
